const CAPS = {
  viewOwnQueue: 0, viewDirectory: 0,
  editRecords: 2, moveWorkItems: 2,
  runAI: 3,
  viewFinancials: 4, advanceDeals: 4, validateSR: 4, signExe: 4,
  manageProjects: 5, manageTransitions: 5,
  applyAI: 6, approveGLCC: 6, signMgr: 6, manageTeam: 6, deleteRecords: 6, viewOrgMatrix: 6, viewAllDepts: 6,
  signHOD: 8, configAutopilot: 8, viewAllTowers: 8, convertAccounts: 8,
  signELT: 10, resetSystem: 10,
  editPnl: 8
};
