/* --- GPS 7-stage single-ticket flow (one ticket, every status) --- */
const GPS7 = [
  { key: "Opportunity", dept: "Client Relationship Mgmt", req: "Opportunity created with line items (item #, description, quantity)" },
  { key: "Quotation (3-Quote)", dept: "Procurement", req: "Deal register + minimum 3 vendor quotes (resell types) → quotation issued" },
  { key: "Margin Approval", dept: "Corporate Governance", req: "Workflow: Exe → Mgr → HOD → ELT — or AI auto-approval" },
  { key: "Service Delivery", dept: "Sales + Procurement", req: "Client PO received & payment term set · Vendor PO(s) raised per GLCC" },
  { key: "Invoice", dept: "Accounts", req: "Customer invoice raised" },
  { key: "Payment & Reconciliation", dept: "Accounts", req: "POP received · vendor paid per GLCC · ledger matched" },
  { key: "Closed", dept: "Client Relationship Mgmt", req: "Handover to Customer Success — account map & renewal cadence" }
];
const gps7Stage = (d) => {
  const A = d.approvals || {};
  const resell = !SERVICE_TYPES.includes(d.type);
  const checks = [
    (d.items || []).length > 0,
    !!(d.gps && d.gps.quoteRef) && (!resell || (d.quotes || []).length >= 3),
    A.Exe && A.Mgr && A.HOD && A.ELT,
    !!(d.clientPO && d.paymentTerm && d.vendorPO),
    !!d.invoiceNo,
    !!(d.pop && d.gps && d.gps.vendorPaid && d.gps.ledgerMatched),
    !!d.closed
  ];
  for (let i = 0; i < checks.length; i++) if (!checks[i]) return i;
  return 6;
};
