    gps_workflow: (db.gpsSRs || []).map((g) => ({ sr: g.srId, opp: g.oppId, queue: GPS_QUEUES[g.queue], vendors: g.vendors.length, awarded: g.awardedVendorIdx >= 0 ? g.vendors[g.awardedVendorIdx].name : null, margin: g.marginPct, finance: g.financeStatus || null, delivery: g.deliveryStatus || null })),
