    onework_itsm: db.itsm ? { open_tickets: db.itsm.tickets.filter((t) => t.status < 3).length, p1_open: db.itsm.tickets.filter((t) => t.priority === "P1" && t.status < 3).length, response_sla_at_risk: db.itsm.tickets.filter((t) => t.status === 0 && itsmRespLeft(t) < 15).length, awaiting_approval: db.itsm.tickets.filter((t) => t.approval === "Pending Approval").length, known_errors: db.itsm.problems.filter((p) => p.status === 2).length, changes_in_cab: db.itsm.changes.filter((c) => c.status === 1).length, automation_rules_enabled: (db.itsm.automations || []).filter((a) => a.enabled).length, virtual_agent: db.itsm.botStats || null } : null,
