/* Gate validation per E2E stage (SOP business rules) */
function gateCheck(deal) {
  const i = deal.stageIndex;
  const svc = SERVICE_TYPES.includes(deal.type);
  switch (i) {
    case 0: return { ok: true, why: "Lead validated." };
    case 1: return { ok: true, why: "Confirm Go / No-Go to advance." };
    case 2: return deal.nda && deal.msa ? { ok: true } : { ok: false, why: "NDA and RSA / MSA must both be executed." };
    case 3: return deal.glccOk ? { ok: true } : { ok: false, why: "GLCC not approved — run the credit decision or approve manually." };
    case 4: return deal.srOk ? { ok: true } : { ok: false, why: "SR must be validated and the solution scoped." };
    case 5: return svc || (deal.quotes || []).length >= 3 ? { ok: true } : { ok: false, why: "Deal register needs minimum 3 vendor quotes (" + (deal.quotes || []).length + "/3)." };
    case 6: { const a = deal.approvals || {}; return a.Exe && a.Mgr && a.HOD && a.ELT ? { ok: true } : { ok: false, why: "Approval chain incomplete — Exe → Mgr → HOD → ELT." }; }
    case 7: return deal.clientPO && deal.paymentTerm ? { ok: true } : { ok: false, why: "Client PO number and payment term are required." };
    case 8: return svc || deal.vendorPO ? { ok: true } : { ok: false, why: "Vendor PO must be raised per GLCC." };
    case 9: return deal.pod ? { ok: true } : { ok: false, why: "POD (with serials / license dates where applicable) not captured." };
    case 10: return deal.invoiceNo ? { ok: true } : { ok: false, why: "Customer invoice not raised." };
    case 11: return deal.pop ? { ok: true } : { ok: false, why: "POP (proof of payment) not received." };
    default: return { ok: false, why: "Deal is closed." };
  }
}

