/* ================= Helpers ================= */
const usd = (n) => "$" + Math.round(Number(n)).toLocaleString("en-US");
const addMonths = (iso, m) => { const d = new Date(iso); d.setMonth(d.getMonth() + m); return d; };
const fmtDate = (d) => new Date(d).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" });
const monthsUntil = (d) => (new Date(d) - TODAY) / (1000 * 60 * 60 * 24 * 30.44);
const monthsSince = (d) => -monthsUntil(d);
const dueInfo = (a) => {
  const due = addMonths(a.deployedOn || a.purchaseDate, a.termMonths);
  const m = monthsUntil(due);
  if (m < 0) return { due, label: "Refresh overdue", tone: "red", months: m };
  if (m <= 3) return { due, label: "Refresh due soon", tone: "amber", months: m };
  return { due, label: "In term", tone: "ok", months: m };
};
const warrantyInfo = (a) => {
  if (!a.warrantyEnd) return null;
  const m = monthsUntil(a.warrantyEnd);
  if (m < 0) return { tone: "red", label: "Warranty expired" };
  if (m <= 3) return { tone: "amber", label: "Warranty ending" };
  return { tone: "ok", label: "In warranty" };
};
const bookValue = (a) => {
  if (a.modelType !== "capex" || !a.cost) return null;
  const v = a.cost * (1 - monthsSince(a.purchaseDate) / a.termMonths);
  return Math.max(0, Math.round(v));
};
let SEQ = 100;
const nid = (p) => `${p}-${++SEQ}`;

