function LevelBar({ pct }) {
  const tone = pct < 40 ? C.red : pct < 60 ? C.amber : C.teal;
  return (
    <div className="relative rounded-full" style={{ height: 8, background: "#DFE5E8" }}>
      <div className="rounded-full" style={{ height: 8, width: Math.min(100, pct) + "%", background: tone }} />
      <div style={{ position: "absolute", left: "40%", top: -2, width: 2, height: 12, background: C.navy, opacity: 0.5 }} title="40% auto-replenishment threshold" />
    </div>
  );
}

function MachinesView({ caps, cl, machines, refills, catalogues, forecast, locations, dispense, collectReturns, advanceRefill, setTracking }) {
  const [tab, setTab] = useState("Smart lockers");
  const canWh = !!caps.advance?.includes("warehouse");
  const openReps = refills.filter((r) => r.stageIndex < r.stages.length);
  const below = machines.filter((m) => mLevel(m) < REFILL_THRESHOLD);
  const list = machines.filter((m) => tab === "Smart lockers" ? m.kind === "locker" : m.kind === "vending");
  const repOf = (m) => refills.find((r) => r.machine === m.id && r.stageIndex < r.stages.length);
  const skuName = (m, sku) => (catalogues[m.client] || []).find((c) => c.id === sku)?.name || sku;
  const siteDemand = (m) => Object.keys(m.slots).reduce((a, sku) => a + Number(forecast[m.location]?.[sku] || 0), 0);
  return (
    <div>
      <SectionTitle kicker="Field operations · unattended endpoints" title="Smart lockers & vending machines"
        right={<Badge tone={below.length ? "red" : "ok"}>{below.length ? `${below.length} below 40% threshold` : "All machines healthy"}</Badge>} />
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-4">
        <Stat label="Machines online" value={machines.length} sub={`${machines.filter((m) => m.kind === "locker").length} lockers · ${machines.filter((m) => m.kind === "vending").length} vending`} />
        <Stat label="Average stock level" value={machines.length ? Math.round(machines.reduce((a, m) => a + mLevel(m), 0) / machines.length * 100) + "%" : "—"} sub="threshold: 40% triggers auto-refill" />
        <Stat label="Open replenishments" value={openReps.length} sub="auto-raised to Warehouse team" />
        <Stat label="Locker returns waiting" value={machines.reduce((a, m) => a + (m.returns || 0), 0)} tone={machines.some((m) => m.returns > 2) ? "amber" : undefined} sub="offboarding drop-offs to collect" />
      </div>
      <div className="flex gap-1 mb-4 flex-wrap" style={{ borderBottom: `2px solid ${C.line}` }}>
        {["Smart lockers", "Vending machines", `Replenishment (${openReps.length})`].map((t) => (
          <button key={t} onClick={() => setTab(t)} className="text-xs font-bold px-3.5 py-2"
            style={{ color: tab === t ? C.tealDark : C.muted, borderBottom: tab === t ? `2px solid ${C.teal}` : "2px solid transparent", marginBottom: -2 }}>{t}</button>))}
      </div>

      {!tab.startsWith("Replenishment") && (
        <div className="grid md:grid-cols-2 gap-4">
          {list.map((m) => {
            const lvl = Math.round(mLevel(m) * 100);
            const rep = repOf(m);
            const days = m.rate ? Math.round(Object.values(m.slots).reduce((a, s) => a + s.qty, 0) / m.rate) : "—";
            return (
              <Card key={m.id} className="p-4">
                <div className="flex items-start gap-3 mb-3">
                  <div className="rounded-lg p-2" style={{ background: C.tealTint }}>{m.kind === "locker" ? <Package size={19} color={C.tealDark} /> : <Boxes size={19} color={C.tealDark} />}</div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="text-sm font-bold" style={{ color: C.ink }}>{m.name}</span>
                      {cl === "all" && <ClientTag id={m.client} />}
                    </div>
                    <div className="text-[11px]" style={{ color: C.faint, ...mono }}>{m.id} · {locations.find((l) => l.id === m.location)?.name}{m.kind === "locker" ? ` · ${m.doors} doors` : ""} · ~{m.rate}/day dispensed</div>
                  </div>
                  {rep ? <Badge tone="sky"><Truck size={10} /> {rep.id}</Badge>
                    : lvl < 40 ? <Badge tone="red"><AlertTriangle size={10} /> Below 40%</Badge>
                      : <Badge tone={lvl < 60 ? "amber" : "ok"}>{lvl < 60 ? "Reorder soon" : "Healthy"}</Badge>}
                </div>
                <div className="flex items-center gap-2 mb-1">
                  <div className="flex-1"><LevelBar pct={lvl} /></div>
                  <span className="text-xs font-extrabold" style={{ ...mono, color: lvl < 40 ? C.red : C.navy }}>{lvl}%</span>
                </div>
                <div className="text-[10px] mb-3" style={{ color: C.faint }}>≈ {days} days of stock at current run-rate · site forecast {siteDemand(m)} units/qtr · marker = 40% auto-trigger</div>
                {!rep && lvl >= 40 && m.rate > 0 && (() => {
                  const tot = Object.values(m.slots).reduce((a, s) => a + s.qty, 0);
                  const cap2 = Object.values(m.slots).reduce((a, s) => a + s.cap, 0);
                  const dd = Math.round((tot - cap2 * 0.4) / m.rate);
                  return dd <= 7 ? <div className="mb-3"><Badge tone="amber"><Sparkles size={10} /> AI forecast: 40% breach in ~{dd}d — pre-emptive refill recommended</Badge></div> : null;
                })()}
                <div className="divide-y" style={{ borderColor: C.line }}>
                  {Object.entries(m.slots).map(([sku, s]) => (
                    <div key={sku} className="py-2 flex items-center gap-2.5">
                      <div className="flex-1 min-w-0">
                        <div className="text-xs font-semibold truncate" style={{ color: C.ink }}>{skuName(m, sku)}</div>
                        <div className="text-[10px]" style={{ ...mono, color: C.faint }}>{sku}</div>
                      </div>
                      <div style={{ width: 90 }}><Bar pct={(s.qty / s.cap) * 100} tone={s.qty / s.cap < 0.4 ? "red" : s.qty / s.cap < 0.6 ? "amber" : "ok"} /></div>
                      <span className="text-xs font-bold w-12 text-right" style={{ ...mono, color: C.muted }}>{s.qty}/{s.cap}</span>
                      <Btn size="sm" kind="subtle" disabled={s.qty === 0} onClick={() => dispense(m.id, sku)}>{m.kind === "locker" ? "Issue" : "Vend"}</Btn>
                    </div>))}
                  {m.kind === "locker" && (
                    <div className="py-2 flex items-center gap-2.5">
                      <div className="flex-1">
                        <div className="text-xs font-semibold" style={{ color: C.ink }}>Returns bin (offboarding drop-offs)</div>
                        <div className="text-[10px]" style={{ color: C.faint }}>Collected devices enter the wiping → destruction → certificate flow</div>
                      </div>
                      <Badge tone={m.returns ? "amber" : "grey"}>{m.returns} device{m.returns === 1 ? "" : "s"}</Badge>
                      {canWh && m.returns > 0 && <Btn size="sm" kind="ghost" onClick={() => collectReturns(m.id)}><PackageCheck size={12} /> Collect</Btn>}
                    </div>)}
                </div>
                <div className="text-[10px] mt-2 rounded-lg p-2" style={{ background: C.mist, color: C.muted }}>
                  <Zap size={10} className="inline mr-1" color={C.tealDark} />Stock intelligence: below 40% a replenishment order auto-raises to the Warehouse team sized to restore 100% capacity{m.kind === "locker" ? "; joiner kits are staged per the JML schedule" : ""}.
                </div>
              </Card>);
          })}
        </div>)}

      {tab.startsWith("Replenishment") && (
        <div className="space-y-3">
          {refills.map((r) => {
            const done = r.stageIndex >= r.stages.length;
            const m = machines.find((x) => x.id === r.machine);
            const cur = r.stages[r.stageIndex];
            const whCanAdv = canWh && !done && r.stageIndex < 3;
            return (
              <Card key={r.id} className="p-4">
                <div className="flex flex-wrap items-center gap-2 mb-3">
                  <span className="text-sm font-extrabold" style={{ ...mono, color: C.navy }}>{r.id}</span>
                  {r.auto && <Badge tone="sky"><Zap size={10} /> Auto-raised by stock intelligence</Badge>}
                  {cl === "all" && <ClientTag id={r.client} />}
                  <span className="text-sm font-semibold" style={{ color: C.ink }}>{m?.name || r.machine}</span>
                  <div className="ml-auto flex items-center gap-2">
                    {done ? <Badge tone="ok"><Check size={11} /> Refill complete</Badge>
                      : r.stageIndex === 3 ? <Badge tone="amber"><HardHat size={10} /> Awaiting field refill · {r.fieldTask}</Badge>
                        : whCanAdv ? <Btn size="sm" onClick={() => advanceRefill(r.id)}>Advance: {cur} <ChevronRight size={13} /></Btn>
                          : <Badge tone="grey"><Timer size={10} /> {cur} — with Warehouse team</Badge>}
                  </div>
                </div>
                <Rail stages={r.stages} active={done ? r.stages.length : r.stageIndex} compact />
                <div className="flex flex-wrap items-center gap-3 mt-2 text-xs" style={{ color: C.muted }}>
                  <span>{r.items.map(({ sku, qty }) => `${qty} × ${skuName(m || { client: r.client, slots: {} }, sku)}`).join("  ·  ")}</span>
                  {r.stageIndex >= 1 && !done && (
                    <span className="flex items-center gap-1.5 ml-auto">
                      <Truck size={12} color={C.tealDark} />
                      <Micro color={C.muted}>Tracking</Micro>
                      {canWh ? <input value={r.tracking || ""} onChange={(e) => setTracking(r.id, e.target.value)} placeholder="Carrier · number"
                        className="rounded-md px-2 py-1 text-xs" style={{ border: `1px solid ${C.line}`, ...mono, width: 190 }} />
                        : <span style={{ ...mono, color: C.ink }}>{r.tracking || "—"}</span>}
                    </span>)}
                  {done && r.tracking && <span className="ml-auto" style={mono}>{r.tracking}</span>}
                </div>
              </Card>);
          })}
          {refills.length === 0 && <Card className="p-6 text-center text-sm" style={{ color: C.muted }}>No replenishment orders — machines are stocked above the 40% threshold.</Card>}
        </div>)}
    </div>
  );
}

/* ================= Field engineers — full module ================= */
const seedCoverage = () => ({
  "LOC-1": { engineers: ["Owen Blake", "Amara Diallo"], cadence: "Resident — daily (Mon–Fri)" },
  "LOC-2": { engineers: ["Chris Novak"], cadence: "Mon / Wed / Fri" },
  "LOC-3": { engineers: ["Anika Rao"], cadence: "Tue & Thu" },
  "LOC-4": { engineers: ["Ken Watanabe"], cadence: "On demand (dispatch)" },
  "LOC-G1": { engineers: ["Sofia Mendes"], cadence: "Tue & Thu" },
  "LOC-G2": { engineers: ["Riya Kaur"], cadence: "1st & 3rd Monday (monthly)" },
  "LOC-I1": { engineers: ["Chris Novak"], cadence: "Weekly — Monday" },
  "LOC-I2": { engineers: ["Ken Watanabe"], cadence: "On demand (dispatch)" },
});
const CADENCES = ["Resident — daily (Mon–Fri)", "Mon / Wed / Fri", "Tue & Thu", "Weekly — Monday", "1st & 3rd Monday (monthly)", "On demand (dispatch)"];
const CAD_DAYS = { "Resident — daily (Mon–Fri)": ["Mon", "Tue", "Wed", "Thu", "Fri"], "Mon / Wed / Fri": ["Mon", "Wed", "Fri"], "Tue & Thu": ["Tue", "Thu"], "Weekly — Monday": ["Mon"], "1st & 3rd Monday (monthly)": ["Mon"], "On demand (dispatch)": [] };
const coverageModel = (u) => u >= 800 ? ["Resident FTE", "navy", "Dedicated engineer(s) embedded on site"] : u >= 200 ? ["Scheduled visits", "sky", "Fixed weekly / monthly visit pattern"] : ["On-demand dispatch", "grey", "Ad-hoc dispatch within the regional SLA"];
const FT_TYPES = ["Incident", "Service request", "Locker", "Vending refill", "RMA", "ITAD", "Deploy"];
const FT_TONE = { Refill: "sky", "Vending refill": "sky", "Break-fix": "red", Incident: "red", Deploy: "navy", Locker: "amber", "Service request": "sky", RMA: "red", ITAD: "navy" };

function FieldOpsView({ cl, techs, tasks, locations, allLocations, coverage, canManage, canAssign, canSDM, hrisOn, enableHris, verifyTech, addTech, setTechStatus, assignTask, advanceTask, addFieldTask, setCadence, addSiteEngineer, removeSiteEngineer, openIncident, autoAssignAll, canWork, rates }) {
  const [tab, setTab] = useState("Dispatch board");
  const [fType, setFType] = useState("All");
  const [n, setN] = useState({ name: "", type: "Dispatch", region: "EMEA", base: "", skills: "" });
  const [nt, setNt] = useState({ type: "Incident", title: "", location: locations[0]?.id, priority: "P3", linked: "" });
  useEffect(() => { if (!locations.some((l) => l.id === nt.location)) setNt((x) => ({ ...x, location: locations[0]?.id })); }, [locations]);
  const verified = techs.filter((t) => t.hrmStatus === "Verified");
  const LL = allLocations || locations;
  const sitesOf = (name) => Object.entries(coverage).filter(([, c]) => c.engineers.includes(name)).map(([loc]) => loc);
  const clientsOf = (name) => [...new Set(sitesOf(name).map((loc) => LL.find((l) => l.id === loc)?.client).filter(Boolean))];
  const sharedLabel = (name) => clientsOf(name).length > 1 ? " · multi-client" : sitesOf(name).length > 1 ? " · shared" : "";
  const openTasks = tasks.filter((t) => t.status !== "Completed");
  const gaps = locations.filter((l) => !(coverage[l.id]?.engineers || []).length);
  const roster = techs.filter((t) => fType === "All" || t.type === fType);
  const typeTone = { FTE: "navy", Scheduled: "sky", Dispatch: "ok" };
  const stTone = { Available: "ok", "On job": "amber", "Off shift": "grey" };
  const locName = (id) => LL.find((l) => l.id === id)?.name || id;
  const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
  return (
    <div>
      <SectionTitle kicker="Field operations · workforce & coverage" title="Field engineers"
        right={hrisOn ? <Badge tone="ok"><Link2 size={11} /> HRM (Workday) connected — verification live</Badge>
          : canSDM ? <Btn size="sm" kind="ghost" onClick={enableHris}><Link2 size={12} /> Enable HRM integration</Btn>
            : <Badge tone="amber">HRM integration disabled</Badge>} />
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-4">
        <Stat label="Engineers" value={techs.length} sub={`${techs.filter((t) => t.type === "FTE").length} FTE · ${techs.filter((t) => t.type === "Scheduled").length} scheduled · ${techs.filter((t) => t.type === "Dispatch").length} dispatch · ${techs.filter((t) => clientsOf(t.name).length > 1).length} multi-client`} />
        <Stat label="HRM verified" value={`${verified.length}/${techs.length}`} tone={verified.length < techs.length ? "amber" : undefined} sub={verified.length < techs.length ? "pending records can't be assigned" : "all records verified via Workday"} />
        <Stat label="Sites covered" value={`${locations.length - gaps.length}/${locations.length}`} tone={gaps.length ? "red" : undefined} sub={gaps.length ? `${gaps.length} coverage gap(s)` : "resident · scheduled · dispatch"} />
        <Stat label="Open field tasks" value={openTasks.length} tone={openTasks.some((t) => !t.tech) ? "amber" : undefined} sub={`${openTasks.filter((t) => !t.tech).length} awaiting assignment`} />
      </div>
      <div className="flex gap-1 mb-4 flex-wrap" style={{ borderBottom: `2px solid ${C.line}` }}>
        {["Dispatch board", "Site coverage", "Weekly schedule", "Roster & HRM"].map((t) => (
          <button key={t} onClick={() => setTab(t)} className="text-xs font-bold px-3.5 py-2"
            style={{ color: tab === t ? C.tealDark : C.muted, borderBottom: tab === t ? `2px solid ${C.teal}` : "2px solid transparent", marginBottom: -2 }}>{t}</button>))}
      </div>

      {tab === "Dispatch board" && (
        <div className="space-y-4">
          {canAssign && (
            <Card className="p-4">
              <div className="flex items-center gap-2 mb-2 flex-wrap">
                <div className="text-sm font-bold" style={{ color: C.ink }}>Raise a field task <span className="text-[10px] font-semibold" style={{ color: C.faint }}>— incidents, service requests, lockers, vending, RMA, ITAD, deployments</span></div>
                {tasks.some((t) => !t.tech && t.status !== "Completed") && <Btn size="sm" kind="ghost" className="ml-auto" onClick={autoAssignAll}><Sparkles size={12} /> AI auto-assign all</Btn>}
              </div>
              <div className="grid sm:grid-cols-6 gap-2 items-end">
                <Field label="Type"><Select value={nt.type} onChange={(e) => setNt({ ...nt, type: e.target.value })}>{FT_TYPES.map((t) => <option key={t}>{t}</option>)}</Select></Field>
                <div className="sm:col-span-2"><Field label="Title / summary"><Input value={nt.title} onChange={(e) => setNt({ ...nt, title: e.target.value })} placeholder="e.g. RMA swap — AST-G1030" /></Field></div>
                <Field label="Site"><Select value={nt.location} onChange={(e) => setNt({ ...nt, location: e.target.value })}>{locations.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}</Select></Field>
                <Field label="Priority"><Select value={nt.priority} onChange={(e) => setNt({ ...nt, priority: e.target.value })}><option>P1</option><option>P2</option><option>P3</option><option>P4</option></Select></Field>
                <Btn disabled={!nt.title.trim()} onClick={() => { addFieldTask({ ...nt, linked: nt.linked || null }); setNt({ ...nt, title: "", linked: "" }); }}><Plus size={14} /> Raise</Btn>
              </div>
            </Card>)}
          <Card className="p-4">
            <div className="divide-y" style={{ borderColor: C.line }}>
              {tasks.map((t) => {
                const idx = FT_STATUS.indexOf(t.status);
                const covEng = (coverage[t.location]?.engineers || []).filter((e) => verified.some((v) => v.name === e));
                const others = verified.filter((x) => x.status !== "Off shift" && !covEng.includes(x.name));
                return (
                  <div key={t.id} className="py-3 flex flex-wrap items-center gap-2">
                    <span className="text-xs font-extrabold" style={{ ...mono, color: C.navy }}>{t.id}</span>
                    <Badge tone={FT_TONE[t.type] || "grey"}>{t.type}</Badge>
                    {cl === "all" && <ClientTag id={t.client} />}
                    <span className="text-sm font-semibold" style={{ color: C.ink }}>{t.title}</span>
                    <Badge tone={PRIO_META[t.priority]?.tone || "grey"}>{t.priority}</Badge>
                    {rates && <Badge tone="grey"><Tags size={9} /> {usd(rates[t.client]?.tasks?.[t.type] || 60)}/visit</Badge>}
                    <span className="text-[11px]" style={{ color: C.faint }}><MapPin size={10} className="inline" /> {locName(t.location)} · {t.scheduled}</span>
                    {t.linked && (String(t.linked).startsWith("INC") ?
                      <button onClick={() => openIncident(t.linked)} className="text-[11px] font-bold underline decoration-dotted" style={{ ...mono, color: C.tealDark }}>↳ {t.linked}</button>
                      : <Badge tone="grey">↳ {t.linked}</Badge>)}
                    <span className="ml-auto flex items-center gap-2 flex-wrap">
                      {t.tech ? <Badge tone="navy"><HardHat size={10} /> {t.tech}{sharedLabel(t.tech)}</Badge>
                        : canAssign ? (
                          <Select value="" onChange={(e) => e.target.value && assignTask(t.id, e.target.value)} style={{ width: 210, fontSize: 12, padding: "4px 8px" }}>
                            <option value="">Assign technician…</option>
                            {covEng.length > 0 && <optgroup label="Covers this site">{covEng.map((e) => <option key={e} value={e}>{e}</option>)}</optgroup>}
                            <optgroup label="Other verified engineers">{others.map((x) => <option key={x.id} value={x.name}>{x.name} · {x.type} · {x.region}</option>)}</optgroup>
                          </Select>
                        ) : <Badge tone="amber">Unassigned</Badge>}
                      <Badge tone={t.status === "Completed" ? "ok" : t.status === "New" ? "amber" : "sky"}>{t.status}</Badge>
                      {(canAssign || canWork) && t.status !== "Completed" && t.tech && (
                        <Btn size="sm" kind="navy" onClick={() => advanceTask(t.id)}>{idx + 1 < FT_STATUS.length ? `→ ${FT_STATUS[idx + 1]}` : "Complete"}</Btn>)}
                    </span>
                  </div>);
              })}
              {tasks.length === 0 && <div className="py-5 text-center text-sm" style={{ color: C.muted }}>No field tasks in scope.</div>}
            </div>
          </Card>
        </div>)}

      {tab === "Site coverage" && (
        <Card style={{ overflowX: "auto" }}>
          <table className="w-full text-sm" style={{ minWidth: 960 }}>
            <thead><tr style={{ borderBottom: `1px solid ${C.line}` }}>
              {["Site", "Users", "Coverage model (by user count)", "Assigned engineers", "Visit cadence", "Status"].map((h) => <th key={h} className="text-left px-4 py-3"><Micro color={C.muted}>{h}</Micro></th>)}
            </tr></thead>
            <tbody>
              {locations.map((l) => {
                const cov = coverage[l.id] || { engineers: [], cadence: "On demand (dispatch)" };
                const [model, tone, hint] = coverageModel(l.users || 0);
                const addable = verified.filter((t) => !cov.engineers.includes(t.name));
                return (
                  <tr key={l.id} style={{ borderBottom: `1px solid ${C.line}` }}>
                    <td className="px-4 py-3">
                      <div className="font-semibold" style={{ color: C.ink }}><MapPin size={12} className="inline mr-1" color={C.teal} />{l.name}</div>
                      <div className="flex gap-1 mt-1">{cl === "all" && <ClientTag id={l.client} />}<Badge tone="grey">{l.region}</Badge></div>
                    </td>
                    <td className="px-4 py-3" style={{ ...mono, color: C.navy, fontWeight: 700 }}>{l.users?.toLocaleString()}</td>
                    <td className="px-4 py-3"><Badge tone={tone}>{model}</Badge><div className="text-[10px] mt-1" style={{ color: C.faint }}>{hint}</div></td>
                    <td className="px-4 py-3">
                      <div className="flex gap-1.5 flex-wrap items-center">
                        {cov.engineers.map((e) => (
                          <Badge key={e} tone={clientsOf(e).length > 1 ? "sky" : "navy"}><HardHat size={10} /> {e}<span title={"Covers: " + sitesOf(e).map(locName).join(", ")}>{sharedLabel(e)}</span>
                            {canSDM && <button onClick={() => removeSiteEngineer(l.id, e)} className="ml-0.5"><X size={10} /></button>}</Badge>))}
                        {canSDM && addable.length > 0 && (
                          <Select value="" onChange={(e) => e.target.value && addSiteEngineer(l.id, e.target.value)} style={{ width: 130, fontSize: 11, padding: "3px 6px" }}>
                            <option value="">+ Add…</option>
                            {addable.map((t) => <option key={t.id} value={t.name}>{t.name}</option>)}
                          </Select>)}
                      </div>
                    </td>
                    <td className="px-4 py-3">
                      {canSDM ? <Select value={cov.cadence} onChange={(e) => setCadence(l.id, e.target.value)} style={{ width: 200, fontSize: 12, padding: "4px 8px" }}>{CADENCES.map((c) => <option key={c}>{c}</option>)}</Select>
                        : <span className="text-xs" style={{ color: C.muted }}>{cov.cadence}</span>}
                    </td>
                    <td className="px-4 py-3">{cov.engineers.length ? <Badge tone="ok"><Check size={10} /> Covered</Badge> : <Badge tone="red"><AlertTriangle size={10} /> Gap</Badge>}</td>
                  </tr>);
              })}
            </tbody>
          </table>
          <div className="text-[11px] p-3" style={{ color: C.faint }}>Model recommendation: ≥ 800 users → resident FTE · 200–799 → scheduled visits (weekly or fixed monthly days) · &lt; 200 → on-demand dispatch. Engineers can be shared across nearby sites and across client accounts — multi-client engineers are highlighted on every site and client they serve, and utilisation is tracked across the combined book of work.</div>
        </Card>)}

      {tab === "Weekly schedule" && (
        <Card style={{ overflowX: "auto" }}>
          <table className="w-full text-xs" style={{ minWidth: 900 }}>
            <thead><tr style={{ borderBottom: `1px solid ${C.line}` }}>
              <th className="text-left px-4 py-3"><Micro color={C.muted}>Engineer</Micro></th>
              {DAYS.map((d) => <th key={d} className="text-left px-2 py-3"><Micro color={C.muted}>{d}</Micro></th>)}
            </tr></thead>
            <tbody>
              {verified.map((t) => {
                const mySites = sitesOf(t.name);
                return (
                  <tr key={t.id} style={{ borderBottom: `1px solid ${C.line}` }}>
                    <td className="px-4 py-2.5">
                      <div className="font-semibold text-sm" style={{ color: C.ink }}>{t.name}</div>
                      <Badge tone={typeTone[t.type]}>{t.type}</Badge>
                    </td>
                    {DAYS.map((d) => {
                      const visits = mySites.filter((loc) => (CAD_DAYS[coverage[loc]?.cadence] || []).includes(d));
                      const onDemand = t.type === "Dispatch" && !visits.length && d !== "Sat" && d !== "Sun";
                      return (
                        <td key={d} className="px-2 py-2.5 align-top">
                          {visits.map((loc) => (
                            <div key={loc} className="rounded-md px-1.5 py-1 mb-1" style={{ background: C.tealTint, color: C.tealDark, fontSize: 10, fontWeight: 700 }}>
                              {locName(loc)}{coverage[loc]?.cadence.includes("monthly") ? " · 1st/3rd" : ""}
                            </div>))}
                          {onDemand && <div className="rounded-md px-1.5 py-1" style={{ background: C.mist, color: C.faint, fontSize: 10 }}>on call</div>}
                        </td>);
                    })}
                  </tr>);
              })}
            </tbody>
          </table>
          <div className="text-[11px] p-3" style={{ color: C.faint }}>Generated from site cadences — resident engineers show daily site blocks, scheduled engineers their visit days (monthly patterns marked 1st/3rd), dispatch engineers stay on call for ad-hoc tasks.</div>
        </Card>)}

      {tab === "Roster & HRM" && (
        <div className="grid lg:grid-cols-3 gap-4">
          <Card className={"p-0 " + (canSDM ? "lg:col-span-2" : "lg:col-span-3")} style={{ overflowX: "auto" }}>
            <div className="flex items-center gap-2 p-4 pb-2 flex-wrap">
              <div className="text-sm font-bold mr-1" style={{ color: C.ink }}>Technician roster</div>
              {["All", "FTE", "Scheduled", "Dispatch"].map((f) => (
                <button key={f} onClick={() => setFType(f)} className="text-[11px] font-semibold rounded-full px-2.5 py-1"
                  style={{ background: fType === f ? C.navy : "#fff", color: fType === f ? "#fff" : C.muted, border: `1px solid ${fType === f ? C.navy : C.line}` }}>{f}</button>))}
            </div>
            <table className="w-full text-sm" style={{ minWidth: 760 }}>
              <thead><tr style={{ borderBottom: `1px solid ${C.line}` }}>
                {["Technician", "Model", "HRM verification", "Sites covered", "Skills", "Status", "Utilisation"].map((h) => <th key={h} className="text-left px-4 py-2.5"><Micro color={C.muted}>{h}</Micro></th>)}
              </tr></thead>
              <tbody>
                {roster.map((t) => {
                  const mySites = sitesOf(t.name);
                  return (
                    <tr key={t.id} style={{ borderBottom: `1px solid ${C.line}`, opacity: t.hrmStatus === "Pending" ? 0.75 : 1 }}>
                      <td className="px-4 py-3"><div className="font-semibold" style={{ color: C.ink }}>{t.name}</div><div className="text-[10px]" style={{ color: C.faint }}>{t.base} · {t.region}{t.rating ? ` · ★ ${t.rating}` : ""}</div></td>
                      <td className="px-4 py-3"><Badge tone={typeTone[t.type]}>{t.type}</Badge><div className="text-[10px] mt-1" style={{ color: C.faint }}>{t.shift}</div></td>
                      <td className="px-4 py-3">
                        {t.hrmStatus === "Verified" ? <><Badge tone="ok"><ShieldCheck size={10} /> Verified</Badge><div className="text-[10px] mt-1" style={{ ...mono, color: C.faint }}>{t.hrmId}</div></>
                          : <><Badge tone="amber"><Timer size={10} /> Pending HRM</Badge>
                            {canSDM && <div className="mt-1"><Btn size="sm" kind="ghost" onClick={() => verifyTech(t.id)}><Link2 size={11} /> Verify via HRM</Btn></div>}</>}
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex gap-1 flex-wrap">{mySites.map((loc) => <Badge key={loc} tone="grey">{locName(loc)}</Badge>)}{clientsOf(t.name).length > 1 ? <Badge tone="sky">Multi-client: {clientsOf(t.name).map(clientName).join(" + ")}</Badge> : mySites.length > 1 ? <Badge tone="sky">Shared</Badge> : null}{!mySites.length && <span className="text-[11px]" style={{ color: C.faint }}>—</span>}</div>
                      </td>
                      <td className="px-4 py-3"><div className="flex gap-1 flex-wrap">{t.skills.map((s) => <Badge key={s} tone="grey">{s}</Badge>)}</div></td>
                      <td className="px-4 py-3">
                        {canManage ? (
                          <Select value={t.status} onChange={(e) => setTechStatus(t.id, e.target.value)} style={{ width: 108, fontSize: 12, padding: "4px 8px" }}>
                            <option>Available</option><option>On job</option><option>Off shift</option>
                          </Select>) : <Badge tone={stTone[t.status]}>{t.status}</Badge>}
                      </td>
                      <td className="px-4 py-3"><div style={{ width: 74 }}><Bar pct={t.util} tone={t.util > 85 ? "red" : t.util < 45 ? "amber" : "ok"} /><div className="text-[10px] mt-0.5" style={{ ...mono, color: C.muted }}>{t.util}%</div></div></td>
                    </tr>);
                })}
              </tbody>
            </table>
          </Card>
          {canSDM && (
            <Card className="p-4 h-fit">
              <div className="text-sm font-bold mb-1" style={{ color: C.ink }}>Add engineer (SDM)</div>
              <div className="text-[11px] mb-3" style={{ color: C.muted }}>New engineers join as <b>Pending</b> and must pass HRM (Workday) verification before they can be assigned to sites or tasks.</div>
              <div className="space-y-3">
                <Field label="Name"><Input value={n.name} onChange={(e) => setN({ ...n, name: e.target.value })} placeholder="e.g. Jamie Fox" /></Field>
                <div className="grid grid-cols-2 gap-2">
                  <Field label="Model"><Select value={n.type} onChange={(e) => setN({ ...n, type: e.target.value })}><option>FTE</option><option>Scheduled</option><option>Dispatch</option></Select></Field>
                  <Field label="Region"><Select value={n.region} onChange={(e) => setN({ ...n, region: e.target.value })}><option>EMEA</option><option>Americas</option><option>APAC</option></Select></Field>
                </div>
                <Field label="Base location"><Input value={n.base} onChange={(e) => setN({ ...n, base: e.target.value })} placeholder="e.g. Austin HQ" /></Field>
                <Field label="Skills (comma-separated)"><Input value={n.skills} onChange={(e) => setN({ ...n, skills: e.target.value })} placeholder="EUC, Vending, ITAD" /></Field>
                <Btn className="w-full justify-center" disabled={!n.name.trim()} onClick={() => { addTech({ ...n, skills: n.skills.split(",").map((s) => s.trim()).filter(Boolean) }); setN({ name: "", type: "Dispatch", region: "EMEA", base: "", skills: "" }); }}>
                  <Plus size={14} /> Add to roster</Btn>
                {!hrisOn && <Btn kind="ghost" className="w-full justify-center" onClick={enableHris}><Link2 size={13} /> Enable HRIS (Workday) integration</Btn>}
              </div>
            </Card>)}
        </div>)}
    </div>
  );
}

/* ================= Claude Enterprise API integration ================= */
const AI_MODEL = "claude-sonnet-4-6";
async function askClaude(prompt, snapshot) {
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: AI_MODEL, max_tokens: 1000,
      messages: [{ role: "user", content: `You are the embedded AI copilot inside Teceze's multi-client Digital Workplace portal (Teceze is an IT MSP). Answer as a concise operations expert: under 130 words, specific, reference record IDs and numbers from the snapshot where relevant, plain text only (no markdown headers).\n\n<platform_snapshot>\n${snapshot}\n</platform_snapshot>\n\nUser: ${prompt}` }],
    }),
  });
  const data = await res.json();
  const txt = (data.content || []).filter((b) => b.type === "text").map((b) => b.text).join("\n").trim();
  if (!txt) throw new Error("empty");
  return txt;
}

/* ================= AI intelligence engine ================= */
const seedAiLog = () => ([
  { t: "09:02", text: "Auto-raised REP for SL-NYC-01 at 37% stock (threshold policy)", area: "machines" },
  { t: "08:47", text: "Auto-resolved INC-1030 (password reset) via self-service flow", area: "incidents" },
  { t: "08:15", text: "Recommended rebalancing 12 × SKU-L100 Dallas → Frankfurt", area: "warehouse" },
]);
const AP_AREAS = [
  ["incidents", "Incident resolution", "Auto-triage new tickets; auto-apply known-error workarounds and resolve"],
  ["machines", "Lockers & vending", "Predictive pre-emptive refills before the 40% threshold breach"],
  ["warehouse", "Warehouse stock", "Rebalance hub stock against aggregated client forecasts"],
  ["field", "Field engineer alignment", "Auto-assign tasks by site coverage, region & utilisation; flag coverage gaps"],
  ["sam", "License optimisation", "Harvest idle licenses and draft true-ups ahead of audits"],
];
function computeInsights(d) {
  const out = [];
  const prio = { red: 0, amber: 1, sky: 2 };
  /* incidents: known-error matches + unassigned triage */
  d.incidents.filter((i) => !["Resolved", "Closed"].includes(i.state)).forEach((i) => {
    const pr = d.problems.find((p) => p.client === i.client && p.workaround !== "—" && ((i.prb && p.id === i.prb) || (p.knownError && p.category === i.category && !i.prb)));
    if (pr) out.push({ id: "ai-inc-" + i.id, area: "incidents", sev: "amber", auto: true, title: `Auto-resolve ${i.id} via known error ${pr.id}`, detail: `"${i.short}" matches ${pr.id} (workaround: ${pr.workaround.slice(0, 60)}…). AI can apply the workaround, attach ${pr.kbA || "the KB"}, and resolve.`, actionLabel: "Apply & resolve", act: { type: "resolve_known", incId: i.id, prbId: pr.id } });
    else if (i.assignee === "—" && i.state === "New") out.push({ id: "ai-tri-" + i.id, area: "incidents", sev: "sky", auto: true, title: `Triage ${i.id} → ${(ASSIGN_GROUPS[i.group] || ["L1"])[0]}`, detail: `New ${incPrio(i)} in ${i.group} is unassigned; best availability is ${(ASSIGN_GROUPS[i.group] || ["L1"])[0]}.`, actionLabel: "Assign", act: { type: "assign_inc", incId: i.id, assignee: (ASSIGN_GROUPS[i.group] || ["L1"])[0] } });
  });
  /* machines: predictive refill */
  d.machines.forEach((m) => {
    if (d.refills.some((r) => r.machine === m.id && r.stageIndex < r.stages.length)) return;
    const tot = Object.values(m.slots).reduce((a, s) => a + s.qty, 0);
    const cap = Object.values(m.slots).reduce((a, s) => a + s.cap, 0);
    if (!m.rate || tot / cap < REFILL_THRESHOLD) return;
    const days = Math.round((tot - cap * REFILL_THRESHOLD) / m.rate);
    if (days <= 7) out.push({ id: "ai-mch-" + m.id, area: "machines", sev: days <= 3 ? "amber" : "sky", auto: true, title: `Pre-emptive refill ${m.id} — breach in ~${days}d`, detail: `${m.name} is at ${Math.round((tot / cap) * 100)}% dispensing ~${m.rate}/day. Raising the replenishment now avoids an empty machine over the shipping window.`, actionLabel: "Raise refill now", act: { type: "preemptive_refill", machineId: m.id } });
  });
  /* warehouse: hub coverage rebalance */
  WAREHOUSES.forEach((w) => {
    const served = d.locations.filter((l) => l.warehouse === w.id).map((l) => l.id);
    const demand = Object.entries(d.forecast).filter(([loc]) => served.includes(loc)).reduce((a, [, m2]) => a + Object.values(m2).reduce((x, y) => x + Number(y || 0), 0), 0);
    const have = Object.values(d.stock[w.id] || {}).reduce((a, b) => a + Number(b || 0), 0);
    if (demand && have / demand < 0.6) {
      const donor = WAREHOUSES.filter((x) => x.id !== w.id).sort((a, b) => Object.values(d.stock[b.id] || {}).reduce((p, q) => p + q, 0) - Object.values(d.stock[a.id] || {}).reduce((p, q) => p + q, 0))[0];
      const sku = Object.keys(d.stock[donor.id] || {}).sort((a, b) => (d.stock[donor.id][b] || 0) - (d.stock[donor.id][a] || 0))[0];
      const qty = Math.min(12, Math.floor((d.stock[donor.id]?.[sku] || 0) / 3));
      if (qty > 0) out.push({ id: "ai-wh-" + w.id, area: "warehouse", sev: "amber", auto: false, title: `Rebalance ${qty} × ${sku} ${donor.id.replace("WH-", "")} → ${w.id.replace("WH-", "")}`, detail: `${w.name} covers only ${Math.round((have / demand) * 100)}% of its forecast; ${donor.name} holds the deepest stock. Inter-hub transfer restores coverage without new purchasing.`, actionLabel: "Create transfer", act: { type: "rebalance", from: donor.id, to: w.id, sku, qty } });
    }
  });
  /* field: gaps, unassigned, overload */
  d.locations.filter((l) => !(d.coverage[l.id]?.engineers || []).length).forEach((l) => {
    const best = d.techs.find((t) => t.hrmStatus === "Verified" && t.region === l.region);
    if (best) out.push({ id: "ai-gap-" + l.id, area: "field", sev: "red", auto: false, title: `Coverage gap at ${l.name}`, detail: `${l.users} users have no assigned engineer. ${best.name} (${best.type}, ${best.region}, ${best.util}% utilised) is the best regional fit.`, actionLabel: `Assign ${best.name}`, act: { type: "coverage_gap", locId: l.id, tech: best.name } });
  });
  d.tasks.filter((t) => !t.tech && t.status !== "Completed").forEach((t) => {
    const covE = (d.coverage[t.location]?.engineers || []).find((e) => d.techs.some((x) => x.name === e && x.hrmStatus === "Verified" && x.status !== "Off shift"));
    const reg = d.locations.find((l) => l.id === t.location)?.region;
    const best = covE || d.techs.filter((x) => x.hrmStatus === "Verified" && x.status === "Available" && x.region === reg).sort((a, b) => a.util - b.util)[0]?.name;
    if (best) out.push({ id: "ai-ft-" + t.id, area: "field", sev: "sky", auto: true, title: `Assign ${t.id} → ${best}`, detail: `${t.type} at ${d.locations.find((l) => l.id === t.location)?.name || t.location}. ${covE ? best + " already covers this site" : "Best regional availability by utilisation"}.`, actionLabel: "Assign", act: { type: "assign_task", taskId: t.id, tech: best } });
  });
  d.techs.filter((t) => t.util > 85).forEach((t) => out.push({ id: "ai-ut-" + t.id, area: "field", sev: "amber", auto: false, title: `${t.name} over-utilised (${t.util}%)`, detail: `Sustained >85% utilisation risks SLA slippage. Consider sharing load with a nearby engineer or adding scheduled coverage.`, actionLabel: null, act: null }));
  /* forecast: missing / understated plans */
  d.locations.forEach((l) => {
    const total = Object.values(d.forecast[l.id] || {}).reduce((a, b) => a + Number(b || 0), 0);
    if (total === 0) out.push({ id: "ai-fc-" + l.id, area: "warehouse", sev: "sky", auto: false, title: `No demand plan for ${l.name}`, detail: `AI can draft a quarterly forecast from headcount (${l.users} users → ~${Math.max(2, Math.round(l.users * 0.05))} laptops, monitors & docks pro-rata).`, actionLabel: "Draft AI forecast", act: { type: "forecast_bump", locId: l.id } });
  });
  /* SAM: true-up + harvest */
  d.titles.filter((t) => t.consumed > t.owned).forEach((t) => out.push({ id: "ai-sam-" + t.id, area: "sam", sev: "red", auto: false, title: `True-up ${t.consumed - t.owned} × ${t.name}`, detail: `${clientName(t.client)} runs ${t.consumed - t.owned} over entitlement — ${usd((t.consumed - t.owned) * t.costMo * 12)}/yr audit exposure. Draft the true-up before renewal (${fmtDate(t.renewal)}).`, actionLabel: "Draft true-up", act: { type: "true_up", titleId: t.id } }));
  const idle = d.inactive.filter((r) => r.last >= 90);
  if (idle.length) out.push({ id: "ai-harv", area: "sam", sev: "amber", auto: false, title: `Harvest ${idle.length} idle license(s)`, detail: `No activity for 90+ days. Reclaiming returns them to the pool immediately and cuts renewal spend.`, actionLabel: "Harvest all", act: { type: "harvest" } });
  return out.sort((a, b) => prio[a.sev] - prio[b.sev]).slice(0, 12);
}

/* ================= Customizable home dashboard ================= */
const MiniBars = ({ data, tone }) => {
  const max = Math.max(1, ...data.map(([, n]) => n));
  return (
    <div className="flex items-end gap-1.5" style={{ height: 84 }}>
      {data.map(([l, n], i) => (
        <div key={l} className="flex-1 flex flex-col items-center gap-0.5">
          <span className="text-[9px] font-bold" style={{ ...mono, color: C.navy }}>{n}</span>
          <div className="w-full rounded-t" style={{ height: Math.max(3, (n / max) * 58), background: i === data.length - 1 ? GRAD.sky : "#C4E8E6" }} />
          <span className="text-[9px]" style={{ color: C.faint }}>{l}</span>
        </div>))}
    </div>);
};
